// Model: an optimiser keeps work only if its result reaches an observed sink.
const N = 1000;
function pureWork(i) { return (i * 31 + 7) % 1009; } // one 'work unit'

// A model optimiser: it eliminates a loop whose result is discarded.
function effectiveWorkUnits({ resultObserved }) {
  // If the result is never observed, DCE removes the body -> 0 units.
  return resultObserved ? N : 0;
}

// Loop 1: result discarded -> eliminable.
for (let i = 0; i < N; i++) { pureWork(i); }
const unusedUnits = effectiveWorkUnits({ resultObserved: false });

// Loop 2: result consumed into a sink read afterwards -> preserved.
let sink = 0;
for (let i = 0; i < N; i++) { sink += pureWork(i); }
const sinkObserved = sink !== undefined; // we read the sink below
const consumedUnits = effectiveWorkUnits({ resultObserved: sinkObserved });

console.log('unused=' + unusedUnits + ' consumed=' + consumedUnits + ' sinkRead=' + sinkObserved);

function hash(s) { /* expensive */ let h = 0; for (const c of s) h = (h * 31 + c.charCodeAt(0)) | 0; return h; }

const t0 = performance.now();
for (let i = 0; i < 1e7; i++) {
  hash('constant-string');     // constant input + result discarded
}
const t1 = performance.now();
console.log('time', t1 - t0);  // single run, from-zero, no warm-up

model.en:
Traps committed: (1) <strong>constant input</strong> — 'constant-string' is a literal, so the hash is constant-folded; (2) <strong>DCE</strong> — the result is discarded, so the body can be eliminated; (3) <strong>no warm-up</strong> — timing from iteration zero blends Ignition/compile into the number; (4) <strong>single run</strong> with no statistics, vulnerable to a stray GC pause. Honest harness:<br><code>const inputs = Array.from({length: 256}, (_, k) =&gt; 'str-' + ((k * 2654435761) &gt;&gt;&gt; 0));
let sink = 0;
// warm up, discard
for (let i = 0; i &lt; 1e5; i++) sink += hash(inputs[i &amp; 255]);
const samples = [];
for (let run = 0; run &lt; 30; run++) {
  const a = performance.now();
  for (let i = 0; i &lt; 1e6; i++) sink += hash(inputs[i &amp; 255]);
  samples.push(performance.now() - a);
}
samples.sort((x, y) =&gt; x - y);
console.log('median', samples[15], 'sink', sink); // read sink so DCE can't fire</code><br>Then verify under <code>--trace-deopt</code> that <code>hash</code> does not bail during the timed runs.

